import { wait } from "#app/lib/time.js";

export async function retry(fn, times) {
  for (let i = 0; ; i++) {
    try {
      return await fn();
    } catch (e) {
      if (i + 1 >= times) throw e;
      await wait(500);
    }
  }
}
